SET NAMES utf8mb4;
-- 005 : apparitions de noeuds, ZONES DE VALIDATION UNIQUEMENT (Elwynn Forest, Durotar, Dun Morogh).
-- Positions = positions de creatures de la table `creature` (jamais inventees) ; guid 9500001-9599999.
-- Echantillon de chaque modele pres de Northshire / Valley of Trials, + noeuds de palier 1 dans les 3 zones.
DELETE FROM `gameobject` WHERE `guid` BETWEEN 9500001 AND 9599999 AND `id` BETWEEN 9101001 AND 9101999;   -- (intégrateur : borné aux nœuds pour ne pas effacer les pièces de construction qui vivent dans la même plage de guid)
